import {starter} from './core.mjs';
export function assistantTemplate(){
 const files=starter();
 files['index.html']='<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My AI assistant</title><link rel="stylesheet" href="styles.css"></head><body><main class="chat"><span class="eyebrow">MY FIRST AI APPLICATION</span><h1>A thoughtful assistant.</h1><p>One focused question. One bounded response.</p><div id="messages" aria-live="polite"></div><form id="chat-form"><label for="question">Your question</label><textarea id="question" maxlength="1500" required placeholder="What would you like to understand?"></textarea><button id="send" type="submit">Ask the assistant</button></form><small>In Studio, every request requires approval. No tools, retries, or background inference.</small></main><script src="app.js"></script></body></html>';
 files['styles.css']+='\n.chat{max-width:640px;margin:auto;padding-top:30px}.chat h1{font-size:40px;letter-spacing:-1.5px}.chat label{display:block;font-size:12px;margin:24px 0 10px}.chat textarea{width:100%;min-height:90px;padding:14px;border:1px solid #cdd9c7;border-radius:8px;font:14px system-ui;resize:vertical}.chat small{display:block;color:#839078;font-size:11px;line-height:1.8;margin-top:22px}.bubble{white-space:pre-wrap;padding:16px 20px;border:1px solid #dbe4d4;background:#fff;border-radius:10px;margin-top:15px;font:13px/1.8 system-ui}.bubble.user{background:#eaf0df}.bubble.error{color:#a64435}';
 files['agent.config.json']=JSON.stringify({name:'My helpful assistant',instructions:'You are a concise, practical assistant. Explain clearly and ask for clarification when needed. Do not claim to browse or use tools.',outputTokens:512},null,2);
 files['app.js']=`const form=document.querySelector('#chat-form'),messages=document.querySelector('#messages'),send=document.querySelector('#send');\nconst pending=new Map();\nfunction bubble(text,kind){const el=document.createElement('div');el.className='bubble '+kind;el.textContent=text;messages.append(el);}\naddEventListener('message',e=>{if(e.source!==parent||e.data?.type!=='agentdock:inference-result')return;const p=pending.get(e.data.requestId);if(!p)return;pending.delete(e.data.requestId);clearTimeout(p.timer);if(e.data.error)p.reject(Error(e.data.error));else p.resolve(e.data.text);});\nfunction askStudio(input){return new Promise((resolve,reject)=>{const requestId=crypto.randomUUID();const timer=setTimeout(()=>{pending.delete(requestId);reject(Error('Request timed out. No automatic retry.'));},90000);pending.set(requestId,{resolve,reject,timer});parent.postMessage({type:'agentdock:inference',requestId,input},'*');});}\nform.addEventListener('submit',e=>e.preventDefault());\nsend.type='button';\nsend.addEventListener('click',async e=>{e.preventDefault();if(send.disabled)return;const input=document.querySelector('#question').value.trim();if(!input)return;send.disabled=true;bubble(input,'user');try{let text;if(parent!==window)text=await askStudio(input);else{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input,confirm:true})});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');text=data.text;}bubble(text,'assistant');}catch(error){bubble(error.message,'error');}finally{send.disabled=false;}});`;
 files['server.mjs']=standaloneAgentServer;
 files['README.md']='# My AI assistant\n\nIn AgentDock, the preview requests inference through the parent Studio gateway. You must approve each call. Edit agent.config.json to change instructions.\n\nOutside Studio: use Node.js 24+, set LLM_MODEL, AZURE_API_KEY, and AZURE_API_BASE locally, then run node server.mjs. Open http://127.0.0.1:4180. No npm packages are required. Use OPENAI_MODEL=openai/gpt-4.1-mini and OPENAI_ENDPOINT for compatible routing, with OPENAI_API_KEY or AZURE_API_KEY kept locally. This exported example supports compatible Chat Completions and Azure v1 and binds to localhost. It is not an authenticated public production server. The request input is your explicit approval when running outside Studio.\n\nDo not deploy this backend publicly without authentication, server-enforced monetary budgets, HTTPS, abuse controls, and operational review. Static ZIP hosting does not run server.mjs.\n';
 files['agentdock.tests.json']=JSON.stringify({steps:[{action:'exists',selector:'#chat-form'},{action:'exists',selector:'#question'}]},null,2);
 return files;
}
const standaloneAgentServer=`import http from 'node:http';
import {readFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const root=path.dirname(fileURLToPath(import.meta.url)),port=4180;
const allowed=new Set(['index.html','styles.css','app.js']);
let busy=false,day='',used=0;
const reply=(res,status,data)=>{res.writeHead(status,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(data));};
http.createServer(async(req,res)=>{try{
 if(req.headers.host!=='127.0.0.1:'+port)return reply(res,403,{error:'Invalid host.'});
 const route=new URL(req.url,'http://127.0.0.1:'+port).pathname;
 if(req.method==='POST'&&route==='/api/chat'){
  if(req.headers.origin!=='http://127.0.0.1:'+port||!req.headers['content-type']?.startsWith('application/json'))return reply(res,403,{error:'Same-origin JSON required.'});
  if(busy)return reply(res,409,{error:'A request is already running.'});busy=true;
  try{let raw='';for await(const chunk of req){raw+=chunk;if(raw.length>4000)throw Error('Input too large.');}const data=JSON.parse(raw);
   if(data.confirm!==true||typeof data.input!=='string'||!data.input.trim()||data.input.length>1500)throw Error('Explicitly submit a question up to 1,500 characters.');
   const config=JSON.parse(await readFile(path.join(root,'agent.config.json'),'utf8'));if(typeof config.instructions!=='string'||config.instructions.length>4000)throw Error('Invalid agent instructions.');
   const key=process.env.OPENAI_API_KEY||process.env.AZURE_API_KEY,configured=process.env.OPENAI_MODEL||process.env.LLM_MODEL||'',compatible=Boolean(process.env.OPENAI_MODEL||process.env.OPENAI_ENDPOINT||configured.startsWith('openai/')),model=configured.replace(/^(openai|azure)\\//,''),base=process.env.OPENAI_ENDPOINT||process.env.AZURE_API_BASE;if(!key||!model||!base)throw Error('Configure Azure environment variables locally.');
   const u=new URL(base);if(u.protocol!=='https:'||u.username||u.password||u.search)throw Error('Use an HTTPS Azure resource endpoint.');
   let p=u.pathname.replace(/\\/+$/,'');if(!compatible&&!p.endsWith('/openai/v1'))p+='/openai/v1';u.pathname=p.endsWith('/chat/completions')?p:p+'/chat/completions';
   const output=Math.min(1024,Math.max(256,Number(config.outputTokens)||512)),messages=[{role:'system',content:config.instructions},{role:'user',content:data.input}];
   const today=new Date().toISOString().slice(0,10);if(day!==today){day=today;used=0;}const reserved=Buffer.byteLength(JSON.stringify(messages))+512+output;
   if(used+reserved>12000)throw Error('Daily in-process allowance reached.');used+=reserved;
   const r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json',...(compatible?{Authorization:'Bearer '+key}:{'api-key':key})},body:JSON.stringify({model,messages,[compatible?'max_tokens':'max_completion_tokens']:output}),signal:AbortSignal.timeout(55000),redirect:'error'});if(!r.ok)throw Error('Provider returned HTTP '+r.status+'. No retry.');const answer=await r.json();return reply(res,200,{text:answer.choices?.[0]?.message?.content||'',reserved});
  }catch{return reply(res,400,{error:'Request failed. Check local configuration and limits. No automatic retry.'});}finally{busy=false;}
 }
 const file=route==='/'?'index.html':route.slice(1);if(req.method!=='GET'||!allowed.has(file))return reply(res,404,{error:'Not found.'});
 const source=await readFile(path.join(root,file));res.writeHead(200,{'Content-Type':file.endsWith('.html')?'text/html':file.endsWith('.css')?'text/css':'text/javascript','X-Content-Type-Options':'nosniff'});res.end(source);
}catch{reply(res,400,{error:'Request failed.'});}}).listen(port,'127.0.0.1',()=>console.log('AI assistant: http://127.0.0.1:'+port));
`;
export function reactTemplate(){
 return {
  'index.html':'<!doctype html>\n<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My React application</title></head><body><div id="root"></div><script type="module" src="./src/main.jsx"></script></body></html>',
  'agentdock.runtime.json':JSON.stringify({entry:'server.mjs',port:3000,build:true},null,2),
  'package.json':JSON.stringify({name:'my-react-application',version:'1.0.0',private:true,type:'module',scripts:{dev:'vite --host 127.0.0.1',build:'vite build',start:'node server.mjs',test:'node --test'},dependencies:{react:'19.3.1','react-dom':'19.3.1',vite:'8.3.5'}},null,2),
  'src/main.jsx':`import React, {useState} from 'react';\nimport {createRoot} from 'react-dom/client';\nimport './style.css';\nfunction App(){const [count,setCount]=useState(0),[backend,setBackend]=useState('Not checked');async function checkBackend(){try{const r=await fetch('/api/health');const data=await r.json();setBackend(data.service||'Ready');}catch{setBackend('Start a live backend in Runtime first.');}}return <main><span className="eyebrow">REACT + NODE STARTER</span><h1>A little idea.<br/>A working application.</h1><p>Edit this component, build it in the isolated runtime, and make it yours.</p><button id="counter" onClick={()=>setCount(count+1)}>Count: {count}</button><section><h2>A backend of your own.</h2><p>The exported Node server serves the compiled application and /api/health. Studio runs its tests in a container; start a live backend in Runtime to call its API here.</p><button id="backend-check" onClick={checkBackend}>Check backend</button><p id="backend-status">{backend}</p></section></main>;}\ncreateRoot(document.getElementById('root')).render(<App/>);\n`,
  'src/style.css':'*{box-sizing:border-box}body{margin:0;background:#f4f6ed;color:#264a37;font:15px/1.8 system-ui}main{padding:65px 10%;max-width:1000px;margin:auto}.eyebrow{font-size:10px;letter-spacing:2px;color:#819371}h1{font-size:clamp(32px,6vw,60px);font-weight:500;line-height:1.1;letter-spacing:-2px}p{max-width:540px;color:#7b8e6f}button{background:#315b40;color:#fff;border:0;border-radius:7px;padding:14px 24px;cursor:pointer}section{margin-top:50px;padding-top:25px;border-top:1px solid #dce5d2}h2{font-weight:500;font-size:20px}',
  'server.mjs':`import http from 'node:http';\nimport path from 'node:path';\nimport {readFile} from 'node:fs/promises';\nimport {fileURLToPath} from 'node:url';\nexport function health(){return {ok:true,service:'my-react-app'};}\nconst root=path.dirname(fileURLToPath(import.meta.url));\nif(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){http.createServer(async(req,res)=>{try{const url=new URL(req.url,'http://127.0.0.1');if(url.pathname==='/api/health'){res.writeHead(200,{'Content-Type':'application/json'});res.end(JSON.stringify(health()));return;}const dist=path.join(root,'dist'),file=path.resolve(dist,'.'+(url.pathname==='/'?'/index.html':decodeURIComponent(url.pathname)));if(!file.startsWith(dist+path.sep))throw Error('Invalid path');const body=await readFile(file);res.writeHead(200,{'Content-Type':file.endsWith('.html')?'text/html':file.endsWith('.css')?'text/css':'text/javascript','X-Content-Type-Options':'nosniff'});res.end(body);}catch{res.writeHead(404);res.end('Not found');}}).listen(Number(process.env.PORT)||4181,'127.0.0.1',()=>console.log('Application port '+(process.env.PORT||4181)));}\n`,
  'server.test.mjs':"import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport {health} from './server.mjs';\ntest('health identifies the application',()=>assert.deepEqual(health(),{ok:true,service:'my-react-app'}));\n",
  'agentdock.tests.json':JSON.stringify({steps:[{action:'exists',selector:'h1'},{action:'click',selector:'#counter'},{action:'wait-text',selector:'#counter',contains:'1',timeout:5000}]},null,2),
  'agentdock.live-tests.json':JSON.stringify({steps:[{action:'exists',selector:'h1'},{action:'click',selector:'#backend-check'},{action:'wait-text',selector:'#backend-status',contains:'my-react-app',timeout:5000}]},null,2),
  'README.md':'# React + Node application\n\nIn Studio, open Runtime and use Build React. The platform owner prepares the trusted image once; project builds use its React/Vite dependencies offline. Node tests run separately in a network-isolated container. Use Runtime > Start current backend for a temporary full-stack preview; its internal port comes from agentdock.runtime.json.\n\nOutside Studio: npm install, npm run build, npm start. Open http://127.0.0.1:4181. Credentials are not exported. Before production hosting, add authentication as needed, deployment configuration, monitoring, and security review.\n'
 };
}
